"use client";

import Link from "next/link";
import { ShoppingCart, ChevronDown } from "lucide-react";
import { useCart } from "@/context/CartContext";
import { useAuth } from "@/context/AuthContext";
import { useState } from "react";
import AuthModal from "./AuthModal";

export default function Navbar() {
  const { cart } = useCart();

  const {
    user,
    logout,
    isLoggedIn,
  } = useAuth();

  const [open, setOpen] = useState(false);

  const [menuOpen, setMenuOpen] =
    useState(false);

  return (
    <>
      <AuthModal
        open={open}
        onClose={() => setOpen(false)}
      />

      <nav className="relative mb-8 flex items-center justify-between rounded-xl bg-white p-5 shadow">

        <Link
          href="/"
          className="text-2xl font-bold"
        >
          📚 Bookshelf
        </Link>

        <div className="flex items-center gap-4">

          <Link
            href="/cart"
            className="flex items-center gap-2 rounded-lg bg-black px-4 py-2 text-white"
          >
            <ShoppingCart size={20} />
            Cart ({cart.length})
          </Link>

          {!isLoggedIn ? (
            <button
              onClick={() => setOpen(true)}
              className="rounded-lg border px-5 py-2 hover:bg-gray-100"
            >
              Login
            </button>
          ) : (
            <div className="relative">

              <button
                onClick={() =>
                  setMenuOpen(!menuOpen)
                }
                className="flex items-center gap-3 rounded-full border px-2 py-1 hover:bg-gray-100"
              >

                <img
                  src={user!.avatar}
                  alt={user!.name}
                  className="h-10 w-10 rounded-full object-cover"
                />

                <span className="font-medium">
                  {user!.name}
                </span>

                <ChevronDown size={18} />

              </button>

              {menuOpen && (

                <div className="absolute right-0 mt-3 w-64 rounded-xl border bg-white shadow-xl">

                  <div className="border-b p-5 text-center">

                    <img
                      src={user!.avatar}
                      className="mx-auto mb-3 h-20 w-20 rounded-full"
                    />

                    <h2 className="font-bold">
                      {user!.name}
                    </h2>

                    <p className="text-sm text-gray-500">
                      {user!.email}
                    </p>

                  </div>

                  <Link
                    href="/profile"
                    className="block px-5 py-3 hover:bg-gray-100"
                  >
                    My Profile
                  </Link>

                 

                  <button
                    onClick={() => {
                      logout();
                      setMenuOpen(false);
                    }}
                    className="w-full px-5 py-3 text-left text-red-600 hover:bg-red-50"
                  >
                    Logout
                  </button>

                </div>

              )}

            </div>
          )}

        </div>

      </nav>
    </>
  );
}